from _rt_dev import M

CODES = ''' Codes: C - connected, S - static, R - RIP derived,
        O - OSPF derived, IA - OSPF inter area route,
        E1 - OSPF external type 1 route, E2 - OSPF external type 2 route
        B - BGP derived, D - DHCP derived, K - kernel route, V - VRRP route
        i - IS-IS, L1 - IS-IS level-1, L2 - IS-IS level-2, ia - IS-IS inter area
        * - FIB route'''

def line_topo(uid, left_net, mid_net="203.0.113.0/24", right=None, pcs=("ПК1", "ПК2")):
    n = [N("P1", "pc", 60, 90, pcs[0], "b"), N("R1", "r", 380, 90, "R1", "b"), N("R2", "r", 720, 90, "R2", "b")]
    e = [E("P1", "R1"), E("R1", "R2")]
    tx = [T(220, 70, left_net, "w", z=16), T(550, 70, mid_net, "w", z=16), T(425, 120, ".1", "g", "start", 16), T(675, 120, ".2", "g", "end", 16)]
    vb = 800
    if right:
        n.append(N("P2", "pc", 1010, 90, pcs[1], "b")); e.append(E("R2", "P2")); tx.append(T(870, 70, right, "w", z=16)); vb = 1080
    return {"vb": [vb, 170], "al": "Линейная топология", "n": n, "e": e, "tx": tx}

