# ================================================================ 44–45. Классификация протоколов
def as_cloud(cid, x, y, lab, sub):
    return [CL(cid, x, y, 400, 300, "")], [T(x, y - 118, lab, "g b", z=19), T(x, y + 132, sub, "dm", z=14)]
ca, ta = as_cloud("A1", 230, 190, "AS 65540", "IGP: RIP, OSPF, IS-IS, iBGP")
cb, tb = as_cloud("A2", 790, 190, "AS 65545", "IGP: RIP, OSPF, IS-IS, iBGP")
topo("t44", {"vb": [1020, 360], "al": "Две автономные системы, связанные eBGP",
             "n": ca + cb + [N("a1", "r", 230, 110, s=1), N("a2", "r", 110, 190, s=1), N("a3", "r", 200, 270, s=1), N("a4", "r", 370, 200, s=1),
                             N("b1", "r", 650, 200, s=1), N("b2", "r", 800, 110, s=1), N("b3", "r", 900, 230, s=1), N("b4", "r", 760, 280, s=1)],
             "e": [E("a1", "a2"), E("a2", "a3"), E("a3", "a4"), E("a1", "a4"), E("a4", "b1", "g", id="t44-eg"), E("b1", "b2"), E("b2", "b3"), E("b3", "b4"), E("b4", "b1")],
             "tx": ta + tb + [T(510, 185, "EGP: eBGP", "g b", z=16)]})
slide("IGP и EGP", head("Классификация протоколов динамической маршрутизации", "Внутренние и внешние протоколы") +
      '<div class="scn"><div class="topo" data-s="1" data-topo="t44"></div></div>' + '<div class="two eq top">' +
      pn(P("Все протоколы маршрутизации делятся на две группы: <g>внешние</g> (EGP, Exterior Gateway Protocol) и <g>внутренние</g> (IGP, Interior Gateway Protocol). Изначально Интернет строился как сеть, объединяющая множество существующих сетей: магистральная сеть (core backbone) и присоединённые к ней автономные системы (AS).")) +
      pn(P("<g>Автономная система</g> — группа сетей и маршрутизаторов под единым административным руководством одной организации, с единой политикой маршрутизации. Маршрутизаторы внутри AS — внутренние шлюзы (IGP), шлюзы, соединяющие AS с магистралью, — внешние (EGP).")) + '</div>')

