# ---------------- Все устройства сети: таблицы на одном слайде
def mini_dev(key):
    from _rt_lib import DEV
    d = DEV[key]; h = f'<div class="pn dvm" data-s="1"><div class="ph"><h3>{d["n"]}</h3><span class="dvk">{d["k"]}</span></div>'
    if d.get("mac"):
        h += '<table class="mini"><tr><th>Порт</th><th>MAC порта</th></tr>' + "".join(f'<tr><td>{r[0]}</td><td>{r[2]}</td></tr>' for r in d["if"]) + '</table>'
        h += '<p class="mh">MAC-таблица</p><table class="mini"><tr><th>MAC</th><th>Порт</th></tr>' + "".join(f'<tr><td>{a}</td><td>{b}</td></tr>' for a, b in d["mac"]) + '</table>'
    else:
        h += '<table class="mini"><tr><th>Интерфейс</th><th>IP</th><th>MAC</th></tr>' + "".join(f'<tr><td>{r[0]}</td><td>{r[1]}</td><td>{r[2]}</td></tr>' for r in d["if"]) + '</table>'
        if d.get("gw"): h += f'<p class="mh">Шлюз: {d["gw"]}</p>'
        h += '<p class="mh">ARP</p><table class="mini"><tr><th>IP</th><th>MAC</th><th>Инт.</th></tr>' + "".join(f'<tr><td>{a}</td><td>{b}</td><td>{c}</td></tr>' for a, b, c in d["arp"]) + '</table>'
        if len(d["rt"][0]) == 4:
            h += '<p class="mh">Маршруты</p><table class="mini"><tr><th>Код</th><th>Сеть</th><th>Next hop</th><th>Инт.</th></tr>' + "".join(f'<tr><td>{a}</td><td>{b}</td><td>{c}</td><td>{e}</td></tr>' for a, b, c, e in d["rt"]) + '</table>'
    return h + '</div>'
slide("Устройства: порты, MAC, таблицы", head("Что хранит каждое устройство", "Порт имеет MAC; у хоста и маршрутизатора есть IP; у коммутатора — таблица коммутации, у маршрутизатора — ARP и маршрутизация", small=True) +
      '<div class="dvgrid">' + "".join(mini_dev(k) for k in ("B_PC1", "B_SW1", "B_R1", "B_R2", "B_SW3", "B_PC3")) + '</div>' +
      grid(icard("link", "У <g>каждого порта</g> свой MAC-адрес. Коммутатор IP-адресов на портах не имеет: он работает по MAC-таблице.", "Канальный уровень", teal=True),
           icard("route", "У хоста и маршрутизатора на интерфейсах есть <g>IP-адрес и маска</g>; ARP-таблица связывает IP соседа с его MAC, таблица маршрутизации выбирает интерфейс.", "Сетевой уровень"), cols="repeat(2,minmax(0,1fr))"))
